    53	/* Sv-39 mode
    54	 * 0x0000_0000_0000_0000-0x0000_003f_ffff_ffff is for user mode
    55	 * 0xffff_ffc0_0000_0000-0xffff_ffff_ffff_ffff is for kernel mode
    56	 */
    57	void setup_vm()
    58	{
    59	    // map kernel virtual address(kva) to kernel physical
    60	    map_kernel_page((PTE *)PGDIR_PA);
    61	    // enable virtual memory
    62	    enable_vm();
    63	}
